            "body": "```도해\n대조: 전자 회로가 10 진수를 쓰면 어떻게 되나\n10 단계로 || 2 단계로\n전압 판단 :: 열 단계를 잰다 || 높다 낮다뿐\n잡음 :: 조금만 흔들려도 || 웬만하면 버틴다\n회로 :: 복잡하고 비싸다 || 단순하다\n= 값의 종류를 줄이는 대신 자릿수를 늘려 안정성을 산 것이다\n```\n\n전선에 흐르는 전압은 온도나 간섭으로 늘 조금씩 흔들린다. 0부터 9까지를 열 개의 전압 단계로 구분하려면 그 흔들림 안에서 단계가 서로 섞인다. 두 단계만 나누면 한참 흔들려도 어느 쪽인지 헷갈리지 않는다.\n\n이 단순함은 다른 데서도 값을 한다. 값이 두 가지뿐이라 전송 중에 뒤집힌 자리를 찾아내는 검사 방식을 만들기 쉽고, 어떤 종류의 데이터든 같은 방식으로 저장하고 옮길 수 있다."
