            "slot": "compare",
            "label": "Process vs Thread",
            "body": "| 특성 | Process | Thread |\n|------|---------|--------|\n| **메모리** | 독립적 | 공유 |\n| **생성 비용** | 높음 | 낮음 |\n| **통신** | IPC 필요 | 직접 가능 |\n| **안정성** | 높음 (격리) | 낮음 (영향) |\n| **컨텍스트 스위칭** | 느림 | 빠름 |\n\n**비유**:\n```\nProcess = 독립된 집\n→ 각자 부엌, 화장실 있음\n→ 이웃집에 가려면 문 나가야 함\n→ 한 집이 무너져도 다른 집은 안전\n\nThread = 같은 집의 방\n→ 부엌, 화장실 공유\n→ 방 사이 이동 쉬움\n→ 불이 나면 전체가 위험\n```\n\n### 언제 Process를 사용할까?\n\n```python\n# ✅ CPU 집약적 작업 → Process 사용\nfrom multiprocessing import Pool\n\ndef calculate_heavy(n):\n    \"\"\"무거운 계산 작업\"\"\"\n    result = 0\n    for i in range(n):\n        result += i ** 2\n    return result\n\nif __name__ == '__main__':\n    # CPU 코어 수만큼 프로세스 생성\n    with Pool(processes=4) as pool:\n        results = pool.map(calculate_heavy, [1000000, 2000000, 3000000, 4000000])\n\n    print(f\"결과: {sum(results)}\")\n\n# Python의 GIL(Global Interpreter Lock) 회피!\n# Process는 각자 독립된 Python 인터프리터 → GIL 영향 없음\n```"
