            "body": "```도해\n대조: 서버를 그대로 인터넷에 열어두면 어떻게 되나\n방화벽 없이 || 방화벽으로\n열린 포트 :: 전부 || 정한 것만\n침투 시도 :: 서버가 받는다 || 앞에서 끊긴다\n나가는 통신 :: 아무 데나 || 허용한 곳만\n= 공격이 닿을 수 있는 면을 줄이는 것이 방화벽이 하는 일이다\n```\n\n인터넷에 그대로 놓인 서버에는 쉬지 않고 접속 시도가 들어온다. 원격 접속이나 데이터베이스 포트처럼 알려진 자리를 자동화된 도구가 계속 두드린다. 열려 있는 포트가 많을수록 그중 하나가 뚫릴 여지도 커진다.\n\n방화벽은 필요한 포트만 열고 나머지를 닫는다. 나가는 쪽도 마찬가지다. 안에서 밖으로 나가는 통신을 제한해두면 악성 프로그램이 데이터를 외부로 보내려 할 때 그 자리에서 막힌다."
