            "body": "```도해\n대조: 한 컴퓨터에서 서비스 여러 개를 돌리면 어떻게 되나\n포트가 없으면 || 포트가 있으면\n프로그램 구분 :: 방법이 없다 || 번호로 가른다\n한 대에 서비스 :: 하나만 || 여럿을 함께\n접속 방법 :: 컴퓨터마다 다름 || 번호가 정해져 있다\n= 컴퓨터 한 대를 여러 창구로 나누는 번호다\n```\n\n서버 한 대에는 대개 여러 프로그램이 함께 돈다. 웹 서버, 데이터베이스, 캐시가 같은 IP 주소를 쓰기 때문에, 도착한 패킷을 누구에게 줄지 정할 기준이 필요하다.\n\n포트 번호가 그 기준이다. 자주 쓰는 서비스에는 번호가 관례로 정해져 있어서, 웹 주소를 칠 때 `:80`이나 `:443`을 따로 적지 않아도 브라우저가 알아서 붙인다."
