            "body": "```도해\n대조: 사설 IP 를 쓰는 기기는 밖에서 어떻게 부르나\n포워딩 없이 || 포워딩으로\n외부 접근 :: 닿지 않는다 || 지정 포트로\n공인 IP :: 기기마다 필요 || 하나로 나눔\n설정 위치 :: 방법이 없다 || 공유기 한 곳\n= 포트 번호로 안쪽 기기를 갈라 쓰는 것이 포워딩이다\n```\n\n집이나 사무실 안 기기들은 `192.168.` 로 시작하는 사설 주소를 쓴다. 이 주소는 인터넷에서 통하지 않아서, 밖에 있는 사람이 그 주소로 보내면 어디에도 닿지 않는다.\n\n공인 IP는 보통 하나뿐이다. 그 하나로 여러 기기를 열려면 구분할 표시가 필요한데 포트 번호가 그 역할을 한다. 8080으로 오면 웹 서버로, 다른 번호로 오면 다른 기기로 보내는 규칙을 공유기에 적어두면 된다."
