        "category": "네트워크",
        "summary": "프록시(Proxy)는 클라이언트를 대신해서 인터넷에 요청을 보내는 중개 서버입니다. 클라이언트의 요청을 받아서 자신의 이름으로 실제 서버에 전달하고, 응답을 다시 클라이언트에게 돌려줍니다.",
        "definition": "이 과정에서 클라이언트의 실제 IP 주소를 감출 수 있으며, 요청과 응답을 캐싱하거나 접근을 제어할 수 있습니다.\n\n프록시가 필요해진 이유는 기업이나 학교 같은 폐쇄된 네트워크 환경에서 외부 인터넷 접근을 통제하고, 보안을 유지하면서도 필요한 사용자들에게만 인터넷 접근을 허용하기 위함입니다. 또한 반복되는 요청의 응답을 캐싱하여 네트워크 트래픽을 줄이고 응답 속도를 높이는 역할도 합니다.",
        "analogy": "🔵 **비유 1**: 학교의 학생들(클라이언트)이 바깥세상(인터넷)과 직접 연락하지 못하고, 학교의 관리실(프록시)을 통해서만 편지를 보낼 수 있는 상황. 관리실에서는 어떤 편지는 받아주고 어떤 편지는 받지 않으며, 편지가 학교에서 오는 것처럼 위장해서 보냅니다.",
        "figure": "```도해\n흐름: Proxy, 무슨 순서로 오가나\n클라이언트 :: google.com 요청 (GET /)\n< Proxy :: 응답 전송 (빠름)\n< Proxy :: 응답 전송\n```",
