          {
            "slot": "why",
            "label": "왜 필요한가",
            "body": "### 문제 1: IPv4 주소 고갈\n전 세계 인터넷 연결 기기 수가 IPv4 주소 수(약 43억)를 훨씬 초과했습니다. 사설 IP를 통해 내부에서는 동일한 주소 범위(192.168.x.x)를 전 세계 모든 가정이 재사용할 수 있어, 이 문제를 실용적으로 해결했습니다.\n\n### 문제 2: 내부 네트워크 보안\n사설 IP는 인터넷에서 직접 라우팅되지 않으므로, 내부 기기가 외부 공격으로부터 기본적으로 보호됩니다. 공유기/방화벽이 없으면 외부에서 직접 사설 IP에 접근할 수 없습니다.\n\n### 문제 3: 네트워크 관리 용이성\n조직 내부에서 IP 주소 체계를 독립적으로 설계하고 관리할 수 있습니다. 공인 IP 할당 기관의 승인 없이 내부 IP를 자유롭게 배정할 수 있습니다."
          },
          {
            "slot": "how",
            "label": "어떻게 작동하나",
            "body": "### 1단계: 내부 기기의 통신 요청\n내부 PC(192.168.1.2)가 인터넷의 웹서버에 접속하려 합니다. 패킷의 출발지 주소는 사설 IP(192.168.1.2)입니다.\n\n### 2단계: NAT 변환 (사설 → 공인)\n공유기가 패킷을 받으면, 출발지 주소를 자신의 공인 IP(203.0.113.5)로 변환합니다. 어떤 내부 기기가 어떤 포트로 요청했는지 NAT 테이블에 기록합니다.\n\n### 3단계: 인터넷 통신\n웹서버는 203.0.113.5에서 온 요청으로 인식하고 응답합니다. 인터넷에서는 내부 사설 IP인 192.168.1.2를 볼 수 없습니다.\n\n### 4단계: NAT 역변환 (공인 → 사설)\n응답 패킷이 공유기에 도착하면, NAT 테이블을 보고 원래 어떤 내부 기기(192.168.1.2)에게 전달해야 하는지 확인하여 전달합니다."
          },
          {
            "slot": "concept",
            "label": "핵심 개념",
            "body": "### 1. 사설 IP 주소 범위 (RFC 1918)\n사설 IP로 사용 가능한 주소 대역은 국제 표준으로 정해져 있습니다:\n- **10.0.0.0 ~ 10.255.255.255** (10.x.x.x): 대규모 기업/클라우드 VPC\n- **172.16.0.0 ~ 172.31.255.255** (172.16~31.x.x): 중간 규모 네트워크\n- **192.168.0.0 ~ 192.168.255.255** (192.168.x.x): 가정/소규모 사무실 (가장 흔함)\n\n### 2. NAT (Network Address Translation)\n사설 IP를 사용하는 기기가 인터넷에 나갈 때, 공유기/라우터가 사설 IP를 공인 IP로 변환합니다. 응답이 돌아오면 다시 사설 IP로 변환하여 해당 기기에 전달합니다. 이를 통해 여러 기기가 하나의 공인 IP를 공유할 수 있습니다.\n\n### 3. 공인 IP의 종류\n- **고정 IP (Static IP)**: 항상 동일한 IP. 서버 운영에 필요. 비용이 더 비쌈\n- **유동 IP (Dynamic IP)**: 접속할 때마다 달라질 수 있는 IP. 가정용 인터넷에 일반적\n- **탄력적 IP (Elastic IP)**: AWS에서 제공하는 고정 공인 IP. 서버에 붙였다 뗄 수 있음\n\n### 4. 루프백 주소와 특수 주소\n- **127.0.0.1 (localhost)**: 자기 자신을 가리키는 주소. 서버 로컬 테스트에 사용\n- **0.0.0.0**: 모든 네트워크 인터페이스. 서버가 어떤 IP에서든 요청을 받겠다는 의미\n- **255.255.255.255**: 브로드캐스트 주소. 네트워크 내 모든 기기에 전송"
          },
          {
            "slot": "compare",
            "label": "무엇과 비교되나",
            "body": "| 항목 | 공인 IP (Public IP) | 사설 IP (Private IP) | IPv6 |\n|------|-------------------|-------------------|------|\n| **범위** | 전 세계 유일 | 조직 내에서만 유일 | 전 세계 유일 |\n| **인터넷 직접 통신** | 가능 | 불가능 (NAT 필요) | 가능 |\n| **주소 고갈 문제** | 있음 (IPv4 한계) | 없음 (재사용 가능) | 없음 (128비트) |\n| **보안** | 직접 노출 | 기본 격리됨 | 직접 노출 |\n| **IP 대역** | IANA 할당 | 10.x, 172.16-31.x, 192.168.x | 2001:/32 등 |\n| **비용** | 유료 (ISP/클라우드) | 무료 (자체 할당) | 유료 (ISP/클라우드) |\n| **서버 운영** | 가능 | Port Forwarding 필요 | 가능 |\n| **변경 가능성** | 동적 IP는 변경됨 | 고정 가능 | 고정 가능 |"
          },
          {
            "slot": "example",
            "label": "실제 사례",
            "body": "### 1. 가정 공유기 환경\n가정 공유기는 ISP(KT, SK, LG U+)로부터 공인 IP(예: 203.0.113.5)를 하나 받습니다. 연결된 기기들에게는 192.168.1.x 사설 IP를 자동으로 배정합니다. 스마트폰, PC, TV 등 여러 기기가 하나의 공인 IP를 공유합니다.\n\n### 2. AWS VPC 환경\nAWS에서 VPC를 만들면 10.0.0.0/16 같은 사설 IP 대역을 설정합니다. Private Subnet의 EC2는 사설 IP만 가지며 인터넷에 직접 접근 불가능합니다. 인터넷 접근이 필요한 Public Subnet의 서버에는 Elastic IP(공인 IP)를 할당합니다.\n\n### 3. 내부 서버에 외부 접근 허용 (Port Forwarding)\n집에서 게임 서버나 NAS를 운영할 때, 공유기에서 Port Forwarding을 설정하여 외부에서 사설 IP의 서버에 접근하게 합니다. 예: 외부에서 203.0.113.5:8080으로 접속하면 공유기가 192.168.1.100:8080으로 포워딩합니다."
          },
          {
            "slot": "tradeoff",
            "label": "장단점",
            "body": "**공인 IP 장점**:\n- 인터넷에서 직접 접근 가능하여 서버 운영에 필수\n- 별도 설정 없이 인터넷 통신 가능\n\n**공인 IP 단점**:\n- 직접 노출되므로 공격 대상이 될 수 있어 방화벽 필수\n- 유료이며 IPv4는 점점 고갈되고 있음\n\n**사설 IP 장점**:\n- 인터넷에 직접 노출되지 않아 기본적인 보호 제공\n- 주소 고갈 걱정 없이 자유롭게 할당 가능\n\n**사설 IP 단점**:\n- 외부에서 접근하려면 Port Forwarding이나 VPN 설정 필요\n- NAT로 인해 일부 P2P 통신이나 특수 프로토콜에서 문제 발생 가능"
          }
