        "definition": "인터넷은 데이터를 작은 조각으로 쪼개 보내는데, 조각은 중간에 사라지기도 하고 순서가 뒤바뀌어 도착하기도 한다. TCP는 빠진 조각을 다시 요청하고 순서를 맞춰서 위층에 넘긴다.",
