        "figure": "```도해\n흐름: 조각 하나가 사라지면 TCP 는 무엇을 하나\n보내는 쪽 :: 파일을 조각내고 번호를 붙여 보낸다\n받는 쪽 :: 1번 받았다, 2번 받았다고 알려준다\n받는 쪽 :: 3번이 안 왔는데 4번이 왔다\n받는 쪽 :: 4번은 들고만 있고 3번을 다시 달라고 한다\n보내는 쪽 :: 3번만 다시 보낸다\n< 받는 쪽 :: 순서대로 맞춰서 위층에 올린다\n= 위층에 있는 HTTP 는 조각이 하나 사라졌다는 사실을 끝내 모른다\n```",
