          {
            "slot": "why",
            "label": "왜 필요한가",
            "body": "### 문제 1: HTTP 폴링의 비효율성\n\n**문제 상황**:\n```javascript\n// HTTP 폴링: 매 1초마다 요청\nsetInterval(() => {\n  fetch('/api/messages')\n    .then(res => res.json())\n    .then(messages => updateChat(messages));\n}, 1000);\n```\n\n**문제점**:\n- 🔴 초당 1000명 × 1요청 = 1000개 요청\n- 🔴 각 요청마다 헤더 1KB → 초당 1MB 낭비\n- 🔴 메시지 없어도 계속 요청\n- 🔴 서버 부하 극심\n\n**WebSocket 해결**:\n```javascript\n// WebSocket: 한 번 연결, 메시지 있을 때만 전송\nconst ws = new WebSocket('ws://example.com/chat');\n\nws.onmessage = (event) => {\n  const message = JSON.parse(event.data);\n  updateChat(message);\n};\n```\n\n**결과**:\n- 네트워크 트래픽 99% 감소\n- 서버 부하 95% 감소\n- 실시간 응답 (지연 시간 < 50ms)\n\n### 문제 2: 실시간 채팅의 지연\n\n**문제 상황 (HTTP)**:\n```\nA: \"안녕\" → 서버 → 폴링 대기 (1초) → B: 수신\nB: \"반가워\" → 서버 → 폴링 대기 (1초) → A: 수신\n\n평균 지연: 0.5 ~ 1초\n```\n\n**WebSocket 해결**:\n```\nA: \"안녕\" → 서버 → 즉시 전송 → B: 수신 (50ms)\nB: \"반가워\" → 서버 → 즉시 전송 → A: 수신 (50ms)\n\n평균 지연: 50ms (20배 빠름)\n```\n\n### 문제 3: 온라인 게임의 동기화\n\n**문제 상황**:\n```javascript\n// HTTP로 게임 상태 업데이트 (불가능)\nsetInterval(() => {\n  fetch('/game/state', {\n    method: 'POST',\n    body: JSON.stringify({ x: player.x, y: player.y })\n  });\n\n  fetch('/game/state')\n    .then(res => res.json())\n    .then(state => updateGame(state));\n}, 100); // 초당 10회 요청 × 100명 = 1000개 요청\n\n// 문제: 지연이 심해서 게임이 끊김\n```\n\n**WebSocket 해결**:\n```javascript\n// WebSocket으로 실시간 동기화\nconst ws = new WebSocket('ws://game.example.com');"
          },
          {
            "slot": "how",
            "label": "어떻게 작동하나",
            "body": "### 전체 흐름\n\n### 핸드셰이크 상세\n\n```도해\n흐름: WebSocket, 무슨 순서로 오가나\nBrowser :: new WebSocket('ws://...')\nClient Code :: GET /chat HTTP/1.1 Host: example.…\nServer :: HTTP/1.1 101 Switching Protocols…\nClient Code :: onopen 이벤트\nBrowser :: WebSocket ready!\n```\n\n### 메시지 전송 과정\n\n```\n1. 애플리케이션 데이터 생성\n   \"Hello World\"\n\n2. 프레임 생성\n   [FIN=1][Opcode=0x1(Text)][Mask=1][Length=11][MaskingKey][Payload]\n\n3. TCP로 전송\n   WebSocket Frame → TCP Segment → IP Packet → Network\n\n4. 서버 수신\n   Network → IP Packet → TCP Segment → WebSocket Frame\n\n5. 프레임 파싱\n   마스킹 해제 → 페이로드 추출 → \"Hello World\"\n\n6. 애플리케이션 핸들러 호출\n   onmessage(event)\n```"
          },
          {
            "slot": "concept",
            "label": "비유",
            "body": "- 📞 **전화 통화**: 양쪽이 동시에 말하고 들을 수 있음\n- 🎮 **멀티플레이 게임**: 모든 플레이어가 실시간으로 상호작용\n- 💬 **메신저 채팅**: 양방향 즉시 메시지 전송"
          },
          {
            "slot": "concept",
            "label": "핵심 개념",
            "body": "### 1. 양방향 통신 (Bidirectional)\n클라이언트와 서버가 동시에 데이터를 주고받을 수 있습니다.\n\n```\nClient <──────────> Server\n       (양방향 통신)\n```\n\n```javascript\n// 클라이언트 → 서버\nws.send('Hello from client');\n\n// 서버 → 클라이언트\nws.onmessage = (event) => {\n  console.log('From server:', event.data);\n};\n```\n\n### 2. 지속적인 연결 (Persistent Connection)\nHTTP와 달리 연결을 계속 유지합니다.\n\n```\nHTTP:  연결 → 요청 → 응답 → 종료 → 연결 → ...\n       (매번 새로운 연결)\n\nWebSocket: 연결 → 데이터 주고받기 → 데이터 주고받기 → ...\n          (한 번 연결, 계속 사용)\n```\n\n### 3. 낮은 지연 시간 (Low Latency)\n헤더 오버헤드가 최소화되어 빠릅니다.\n\n```\nHTTP 요청/응답:\n- 요청 헤더: 500-1000 바이트\n- 응답 헤더: 300-500 바이트\n- 실제 데이터: 100 바이트\n→ 총 1000+ 바이트\n\nWebSocket 프레임:\n- 프레임 헤더: 2-14 바이트\n- 실제 데이터: 100 바이트\n→ 총 102-114 바이트 (90% 감소!)\n```\n\n### 4. 프로토콜 전환 (Protocol Upgrade)\nHTTP로 시작해서 WebSocket으로 전환됩니다.\n\n```http\n// 1단계: HTTP 핸드셰이크\nGET /chat HTTP/1.1\nHost: example.com\nUpgrade: websocket\nConnection: Upgrade\n\n// 2단계: 서버 응답\nHTTP/1.1 101 Switching Protocols\nUpgrade: websocket\nConnection: Upgrade\n\n// 3단계: WebSocket 통신 시작\n```\n\n### 5. 프레임 기반 통신 (Frame-Based)\n데이터는 프레임 단위로 전송됩니다.\n\n```javascript\n// 텍스트 프레임\nws.send('Hello');\n\n// 바이너리 프레임\nconst buffer = new ArrayBuffer(8);\nws.send(buffer);\n\n// JSON 프레임\nws.send(JSON.stringify({ type: 'message', text: 'Hi' }));\n```"
          },
          {
            "slot": "compare",
            "label": "WebSocket vs SSE vs Long Polling",
            "body": "| 구분 | WebSocket | SSE | Long Polling |\n|------|-----------|-----|--------------|\n| **방향** | 양방향 | 단방향 (서버→클라) | 단방향 |\n| **프로토콜** | ws:// / wss:// | HTTP | HTTP |\n| **재연결** | 수동 | 자동 | 수동 |\n| **바이너리** | 지원 | 미지원 | 미지원 |\n| **복잡도** | 중간 | 낮음 | 높음 |\n| **지연시간** | 매우 낮음 (10-50ms) | 낮음 (50-200ms) | 높음 (500-2000ms) |\n| **서버 부하** | 낮음 | 낮음 | 높음 |\n| **적합한 용도** | 채팅, 게임, 협업 | 알림, 피드, 로그 | 간단한 업데이트 |\n| **프록시** | 어려움 | 쉬움 | 쉬움 |"
          },
          {
            "slot": "example",
            "label": "코드 구현",
            "body": "### 예시 1: 클라이언트 기본 구현\n\n```javascript\n// WebSocket 연결 생성\nconst ws = new WebSocket('ws://localhost:8080/chat');\n\n// 연결 열림\nws.onopen = (event) => {\n  console.log('Connected to server');\n\n  // 서버에 메시지 전송\n  ws.send('Hello Server!');\n\n  // JSON 데이터 전송\n  ws.send(JSON.stringify({\n    type: 'join',\n    username: '홍길동'\n  }));\n};\n\n// 메시지 수신\nws.onmessage = (event) => {\n  console.log('Received:', event.data);\n\n  // JSON 파싱\n  try {\n    const data = JSON.parse(event.data);\n    handleMessage(data);\n  } catch (e) {\n    console.log('Plain text:', event.data);\n  }\n};\n\n// 에러 처리\nws.onerror = (error) => {\n  console.error('WebSocket error:', error);\n};\n\n// 연결 종료\nws.onclose = (event) => {\n  console.log('Disconnected:', event.code, event.reason);\n\n  if (event.code === 1006) {\n    console.log('Abnormal closure, attempting reconnect...');\n    reconnect();\n  }\n};\n\n// 메시지 전송 함수\nfunction sendMessage(message) {\n  if (ws.readyState === WebSocket.OPEN) {\n    ws.send(JSON.stringify(message));\n  } else {\n    console.error('WebSocket is not open');\n  }\n}\n\n// 연결 종료\nfunction disconnect() {\n  ws.close(1000, 'User initiated close');\n}\n```\n\n### 예시 2: 서버 구현 (Node.js + ws)\n\n```javascript\nconst WebSocket = require('ws');\nconst wss = new WebSocket.Server({ port: 8080 });\n\n// 연결된 클라이언트 관리\nconst clients = new Set();\n\nwss.on('connection', (ws, req) => {\n  console.log('New client connected');\n  clients.add(ws);"
          }
