            "slot": "compare",
            "label": "curl vs 다른 도구",
            "body": "| 도구 | 특징 | 사용 시기 |\n|------|------|----------|\n| **curl** | 명령줄, 스크립트 자동화 | 서버, 자동화, 빠른 테스트 |\n| **wget** | 파일 다운로드 특화, 재귀 다운로드 | 웹사이트 전체 다운로드 |\n| **Postman** | GUI, 시각적, 컬렉션 관리 | 복잡한 API 개발/문서화 |\n| **httpie** | 사용자 친화적 CLI | 터미널에서 예쁜 출력 |\n\n**선택 가이드**:\n```\n빠른 테스트 → curl\n자동화 스크립트 → curl\n파일 다운로드 → curl / wget\nGUI 필요 → Postman\n예쁜 CLI → httpie\n```"
