        "definition": "사용자가 보는 것은 화면뿐이지만, 로그인이 맞는지 판단하고 값을 계산하고 데이터를 저장하는 일은 전부 서버에서 일어난다. 그 부분을 백엔드라고 부른다.",
        "analogy": "식당의 주방. 손님은 홀에서 메뉴판을 보고 주문하지만, 재료를 확인하고 조리하고 재고를 줄이는 일은 안에서 일어난다.",
        "figure": "```도해\n흐름: 주문 버튼을 누르면 서버에서 무슨 일이 일어나나\n사용자 :: 화면에서 주문 버튼을 누른다\n프론트 :: 주문 내용을 서버로 보낸다\n백엔드 :: 로그인한 사람이 맞는지 확인한다\n백엔드 :: 재고를 보고 주문을 데이터베이스에 쓴다\n< 프론트 :: 결과를 받아 \"주문 완료\"를 띄운다\n= 판단하고 저장하는 일은 전부 서버 쪽에서 끝난다\n```",
