            "slot": "why",
            "label": "왜 필요한가",
            "body": "```도해\n대조: API 주소를 각자 편한 대로 지으면 어떻게 되나\n제각각일 때 || REST 로\n주소 :: 동작까지 넣는다 || 대상만 가리킨다\n동작 구분 :: 이름으로 짐작 || 메서드로 명시\n처음 보는 API :: 문서를 다 읽어야 || 형태로 짐작 가능\n= 같은 규칙을 따르면 안 배운 API 도 절반은 읽힌다\n```\n\n주소를 짓는 방식에 합의가 없으면 같은 회사 안에서도 API 마다 규칙이 달라진다. 어떤 곳은 `/getUser`, 어떤 곳은 `/user/fetch`, 또 어떤 곳은 `/user?action=get` 이 된다. 쓰는 쪽은 매번 문서를 처음부터 읽어야 하고, 만드는 쪽도 새 기능마다 이름을 놓고 고민한다.\n\nREST 는 이 자리를 둘로 나눠 고정한다. 주소는 대상만 가리키고 동작은 메서드가 맡는다. 규칙이 같으면 처음 보는 API 도 목록 조회와 삭제쯤은 문서 없이 짐작할 수 있다."
