            "slot": "compare",
            "label": "무엇과 비교되나",
            "body": "| 항목 | Webhook | Polling | WebSocket | SSE(Server-Sent Events) |\n|------|---------|---------|-----------|--------------------------|\n| **통신 방향** | 서버 → 클라이언트 (푸시) | 클라이언트 → 서버 | 양방향 (풀더플렉스) | 서버 → 클라이언트 (단방향) |\n| **프로토콜** | HTTP POST | HTTP GET | WebSocket | HTTP |\n| **실시간성** | 높음 (이벤트 기반) | 낮음 (지연 가능) | 매우 높음 | 높음 |\n| **네트워크 효율** | 효율적 | 비효율적 | 매우 효율적 | 효율적 |\n| **서버 부하** | 낮음 | 높음 | 중간 | 중간 |\n| **구현 복잡도** | 중간 | 낮음 | 높음 | 중간 |\n| **브라우저 지원** | 우수 | 우수 | 우수 | 우수 |\n| **사용 사례** | 이벤트 알림, CI/CD | 간단한 상태 확인 | 실시간 채팅, 게임 | 실시간 뉴스 피드 |"
