        "summary": "Snowflake는 **클라우드 기반 데이터 웨어하우스 플랫폼**입니다. 대용량 데이터를 저장하고 분석하는 데 최적화되어 있으며, 자동 스케일링과 간편한 관리가 특징입니다.",
        "definition": "",
