            "body": "```도해\n대조: 남이 만든 기능을 쓰려면 어떻게 해야 하나\nAPI 없이 || API 로\n날씨 기능 :: 직접 다 만든다 || 불러 쓴다\n상대의 변경 :: 같이 깨진다 || 창구는 그대로\n연동 방식 :: 서비스마다 제각각 || 정해진 규칙\n= 창구를 정해두면 안쪽이 바뀌어도 쓰는 쪽이 안 흔들린다\n```\n\n기능을 하나 붙일 때마다 처음부터 만들면 시간이 아무리 많아도 모자란다. 지도, 결제, 번역, 인증은 이미 잘 만들어진 것이 있고 그걸 부르는 편이 낫다.\n\n혼자 만든 코드 안에서도 마찬가지다. 함수 이름과 넘길 값만 정해두면, 그 함수를 나중에 통째로 다시 짜도 부르는 쪽 코드는 손댈 필요가 없다. API가 하는 일은 결국 이 경계를 그어두는 것이다."
