            "body": "**문제 상황**:\n```\n😱 시나리오: 하드코딩된 IP\n주문 서비스 → 결제 서비스(192.168.1.100:8080)\n→ 결제 서비스 재시작 → IP 변경됨\n→ 연결 실패! 😱\n```\n\n**Service Discovery의 해결**:\n```\n✅ 자동 발견:\n결제 서비스 → 레지스트리에 등록\n주문 서비스 → 레지스트리 조회\n→ 최신 IP 자동 발견\n→ 항상 연결 성공! ✅\n```\n\n**비유**:\n- **하드코딩** = 친구 이사 시 새 주소 못 찾음\n- **Service Discovery** = 주소록 자동 업데이트"
