        "analogy": "도서관의 분관. 장서가 백만 권이 되면 한 건물에 다 넣을 수 없다. ㄱ부터 ㅅ은 본관, ㅇ부터 ㅎ은 분관에 두면 각 건물은 감당할 만해진다. 대신 어느 책이 어디 있는지 아는 규칙이 있어야 한다.",
