            "slot": "myth",
            "label": "흔히 잘못 아는 것",
            "body": "- **OAuth는 로그인 방식이다** — 인가(무엇을 할 수 있는가)를 다루는 규약이지 인증(누구인가)이 아니다. 로그인에 쓰려면 그 위에 얹은 [[OIDC]]가 필요하다.\n- **토큰이 있으면 무엇이든 할 수 있다** — 동의한 범위 안에서만 된다. 캘린더 읽기 토큰으로 메일을 읽을 수 없다.\n- **한 번 동의하면 영구적이다** — 사용자가 계정 설정에서 언제든 회수할 수 있고, 그러면 토큰이 즉시 죽는다."
