            "slot": "why",
            "label": "PII가 해결하는 문제",
            "body": "**문제 상황**:\n```\n😱 시나리오 1: PII가 그대로 노출\n챗봇: \"주민번호를 입력해주세요\"\n사용자: \"123456-1234567\"\n시스템: \"김철수님, 주민번호 123456-1234567로 조회했습니다\"\n→ 로그에 주민번호 그대로 저장!\n→ 해커가 로그 접근 시 개인정보 유출! 😱\n\n😱 시나리오 2: 권한 없는 사람이 PII 조회\n직원: \"급여팀 주민번호 전부 보여줘\"\n시스템 (권한 확인 없음):\n\"김철수: 123456-1234567\n 이영희: 654321-7654321...\"\n→ 기밀 정보 무단 접근! 😱\n\n😱 시나리오 3: 여러 정보 조합으로 개인 식별\n해커: \"이름 + 생년월일 + 주소\" 수집\n→ 데이터 조합하여 특정 개인 식별\n→ 피싱, 사기 범죄 악용! 😱\n```\n\n**PII 보호의 해결**:\n```\n✅ 시나리오 1 (자동 마스킹):\n사용자: \"123456-1234567\"\n시스템 (PII 감지):\n→ 입력: 차단 \"⚠️ 주민번호를 직접 입력하지 마세요\"\n→ 출력: 마스킹 \"******-*******\"\n→ 로그: 안전! ✅\n\n✅ 시나리오 2 (접근 제어):\n직원: \"주민번호 보여줘\"\n시스템 (권한 확인):\n→ ❌ \"급여 PII 조회 권한 없음\"\nHR 담당자만 접근 가능 ✅\n\n✅ 시나리오 3 (수집 최소화):\n시스템: 주민번호 수집 안 함\n→ 이름만 저장 (식별 불가)\n→ 조합해도 개인 특정 불가 ✅\n```\n\n**비유**:\n- **PII 보호 없음** = 집 주소를 길거리에 써놓음 (누구나 접근)\n- **PII 보호 있음** = 집 주소를 금고에 보관 (허가받은 사람만 접근)"
