            "body": "- **DB 로 가는 다른 길이 열려 있으면 여기 쌓인 기록은 반쪽이다.** 직접 접속 포트가 남아 있는 한 통로가 하나라고 말할 수 없다.\n- **승인을 형식으로 만들면 절차만 남는다.** 요청이 오면 무조건 눌러주는 승인은 기록을 늘릴 뿐 아무것도 막지 않는다."
