        "term": "SQL Injection",
        "reading": "SQL 삽입",
        "category": "보안 · 인증",
        "summary": "SQL Injection은 **입력값이 데이터가 아니라 명령으로 실행되는 공격**이다.",
        "definition": "로그인 칸에 아이디 대신 SQL 문법 조각을 넣으면, 서버가 그것을 문자열이 아니라 질의문의 일부로 읽는다. 그러면 비밀번호 없이 로그인하거나 테이블을 통째로 지울 수 있다.",
        "analogy": "받아쓰기와 지시의 혼동. 비서에게 \"이 문장을 받아 적어: 모든 서류를 파쇄하라\"고 말했는데 비서가 받아 적는 대신 실제로 파쇄해버리는 상황이다.",
        "figure": "```도해\n흐름: 아이디 칸에 따옴표를 넣으면 무슨 일이 생기나\n공격자 :: 아이디 칸에 `' OR '1'='1` 을 입력한다\n서버 :: 입력값을 질의문 문자열에 그대로 이어 붙인다\n질의문 :: 조건이 항상 참이 되도록 바뀐다\nDB :: 문법상 올바른 질의라 그대로 실행한다\n< 공격자 :: 첫 번째 사용자로 로그인된다\n= 문제는 입력값이 아니라 문자열을 이어 붙인 방식이다\n```",
