            "slot": "how",
            "label": "어떻게 작동하나",
            "body": "```도해\n층: 어디서 막을 수 있나\n파라미터 바인딩 :: 여기서 막힌다. 유일하게 확실한 층\n최소 권한 :: 뚫려도 삭제 권한이 없으면 피해가 준다\n입력 검증 :: 도움은 되지만 이것만으로는 못 막는다\n= 위층 하나가 제대로면 아래는 보조다. 반대는 성립하지 않는다\n```\n\nORM을 쓰면 대체로 안전하지만 자동으로 안전한 것은 아니다. 원시 질의문을 직접 쓰는 기능이 대부분의 ORM에 있고, 거기서 문자열을 이어 붙이면 똑같이 뚫린다."
