            "body": "- **SSO는 비밀번호가 같은 것이다** — 다르다. 비밀번호를 여러 곳에 똑같이 쓰는 것(SSO가 아닌 것)과, 비밀번호를 한 곳에만 두는 것(SSO)은 정반대다.\n- **SSO가 있으면 더 안전하다** — 계정 하나가 뚫리면 전부 뚫린다. 그래서 SSO에는 다단계 인증이 사실상 필수다.\n- **로그아웃하면 전부 로그아웃된다** — 서비스마다 자기 세션을 따로 갖고 있어서, 전체 로그아웃은 별도로 구현해야 한다."
