            "slot": "caution",
            "label": "Token 보안 Best Practices",
            "body": "### 1. Token 만료 시간 설정\n\n```python\n# ✅ 좋은 예\nAccess Token: 15분~1시간 (짧게)\nRefresh Token: 7일~30일 (길게)\n\n# ❌ 나쁜 예\nAccess Token: 30일 (너무 길어서 위험)\n```\n\n### 2. Token 블랙리스트\n\n```python\n# 로그아웃 시 Token 무효화\nblacklisted_tokens = set()\n\ndef logout(token: str):\n    \"\"\"Token을 블랙리스트에 추가\"\"\"\n    blacklisted_tokens.add(token)\n\ndef is_token_blacklisted(token: str) -> bool:\n    \"\"\"블랙리스트 확인\"\"\"\n    return token in blacklisted_tokens\n```\n\n### 3. HTTPS 필수\n\n```python\n# Token은 반드시 HTTPS로 전송\nif not request.is_secure:\n    raise Exception(\"HTTPS 연결이 필요합니다\")\n```\n\n### 4. Token에 민감 정보 포함 금지\n\n```python\n# ❌ 나쁜 예\npayload = {\n    'user_id': 'user123',\n    'password': 'secret123',  # ❌ 비밀번호 포함 금지!\n    'ssn': '123456-1234567'   # ❌ PII 포함 금지!\n}\n\n# ✅ 좋은 예\npayload = {\n    'user_id': 'user123',\n    'role': 'admin',\n    'exp': ...\n}\n```"
