        "summary": "XSS는 **남의 브라우저에서 내 스크립트를 실행시키는 공격**이다.",
        "definition": "댓글이나 프로필에 스크립트를 심어두면, 그 페이지를 여는 다른 사용자의 브라우저가 그것을 실행한다. 공격자는 그 사람의 쿠키를 훔치거나 그 사람인 척 요청을 보낼 수 있다.",
