        "figure": "```도해\n흐름: 댓글 하나가 남의 계정을 어떻게 털어가나\n공격자 :: 댓글에 스크립트 태그를 넣어 저장한다\n서버 :: 그 문자열을 그대로 DB 에 저장한다\n피해자 :: 게시글을 연다\n서버 :: 댓글을 HTML 에 그대로 끼워 넣어 보낸다\n브라우저 :: 스크립트로 인식하고 실행한다\n< 공격자 :: 피해자의 쿠키가 공격자 서버로 전송된다\n= 공격자는 피해자를 만난 적도 없고 피해자는 클릭한 적도 없다\n```",
