            "body": "이 항목은 해결하는 문제가 아니라 **막아야 할 공격**이다.\n\n```도해\n대조: 사용자 입력을 화면에 어떻게 넣나\n그대로 넣기 || 이스케이프\n`<script>` :: 태그로 실행된다 || 글자로 보인다\n따옴표 :: 속성을 끊는다 || 글자로 보인다\n방어 방식 :: 나쁜 것을 찾아 지움 || 전부 글자 취급\n= 무엇이 위험한지 목록을 만드는 대신, 전부 글자로 취급하는 쪽이 이긴다\n```\n\n[[SQL Injection]]과 뿌리가 같다. 데이터로 들어온 것이 명령으로 해석되는 문제다. 다만 실행되는 곳이 데이터베이스가 아니라 사용자의 브라우저라는 점이 다르고, 그래서 피해자가 서버가 아니라 다른 사용자다.\n\n막는 방법도 같은 성격이다. 위험한 문자를 찾아 지우는 대신, 화면에 넣는 모든 값을 글자로만 취급하도록 이스케이프한다."
