            "body": "```도해\n대조: 공격자가 사내망 안으로 들어오면 어떻게 되나\n경계 방어 || 제로 트러스트\n내부 이동 :: 자유롭다 || 매번 막힌다\n재택 근무 :: VPN 으로 내부 취급 || 어디서든 같은 검사\n피해 범위 :: 전체로 번진다 || 그 자원 하나\n= 안과 밖을 나누는 선이 이미 무의미해졌다는 인정에서 출발한다\n```\n\n전통적인 보안은 성벽 모델이었다. 방화벽으로 안과 밖을 나누고, 안에 들어온 것은 믿는다. 이 모델은 직원이 사무실에서만 일하고 서버가 사내에만 있을 때 성립했다.\n\n지금은 그 전제가 깨졌다. 직원은 집과 카페에서 일하고 서버는 클라우드에 있고 협력사도 사내 시스템을 쓴다. 무엇보다 공격자가 직원 계정 하나만 뚫으면 그 성벽 안쪽에 서게 된다. 안에 들어온 것을 믿는 순간 나머지가 전부 열린다."
