        "category": "클라우드",
        "summary": "Region은 **클라우드 업체가 한 지역에 세운 독립된 데이터센터 묶음**이다.",
        "definition": "리전끼리는 수천 킬로미터 떨어져 있고 전원과 네트워크도 따로 쓴다. 그래서 한 리전에서 난 사고가 다른 리전으로 번지지 않고, 어느 리전에 두느냐가 곧 지연과 규제와 요금을 정한다.",
        "analogy": "체인점의 지역 창고. 간판은 같아도 창고마다 재고가 따로라, 서울에 없는 물건이 부산에는 있다.",
        "figure": "```도해\n흐름: 한국 사용자의 요청은 어디로 가나\n사용자 :: 사이트 주소를 연다\nDNS :: 접속 지역을 보고 리전을 고른다\n서울 리전 :: 그 리전의 로드 밸런서가 받는다\n서버 :: 같은 리전의 DB 에서 데이터를 읽는다\n< 사용자 :: 가까운 곳에서 처리된 응답을 받는다\n= 리전이 여럿이면 요청 하나는 가장 가까운 한 곳에서 끝난다\n```",
