            "body": "```도해\n대조: 데이터베이스의 LIKE 검색은 무엇이 아쉬운가\nLIKE 검색 || 색인 검색\n속도 :: 행을 다 훑는다 || 색인만 본다\n어미 변화 :: 못 찾는다 || 같은 말로 본다\n정렬 :: 관련도가 없다 || 점수로 매긴다\n= 값이 일치하는 행을 찾는 일과 글 속에서 찾는 일은 도구가 다르다\n```\n\n`LIKE '%주소%'` 같은 조건은 앞이 열려 있어서 색인을 못 쓴다. 행 수가 늘면 전체를 훑는 시간이 그대로 늘고, \"주소 변경\"으로 검색했을 때 \"변경 주소\"가 적힌 문서는 못 찾는다.\n\nElastic Search 는 문서를 넣는 순간 단어로 쪼개 어느 문서에 들어 있는지 적어둔다. 검색은 그 목록을 보는 일이라 문서 수가 늘어도 크게 느려지지 않고, 겹치는 단어 수와 희소성으로 점수를 매겨 관련도 순으로 돌려준다."
