            "slot": "compare",
            "label": "무엇과 비교되나",
            "body": "| 항목 | Type 1 (Bare Metal) | Type 2 (Hosted) |\n|------|---------------------|-----------------|\n| **설치 위치** | 물리 하드웨어 위에 직접 설치 | 호스트 OS 위에 설치 |\n| **호스트 OS** | 없음 | Windows, macOS, Linux 등 |\n| **성능** | 매우 높음 (최소 오버헤드) | 낮음 (호스트 OS 계층으로 인한 오버헤드) |\n| **하드웨어 접근** | 직접 | 호스트 OS를 통해 간접 |\n| **보안** | 높음 (OS 계층이 없어 공격 범위 축소) | 낮음 (호스트 OS 취약성 영향) |\n| **사용 대상** | 엔터프라이즈, 데이터 센터 | 개발자, 테스트, 학습 |\n| **설치 복잡도** | 높음 (하드웨어와 호환성 확인 필요) | 낮음 (기존 OS에 애플리케이션처럼 설치) |\n| **라이선스** | 상용 제품 비용 높음 | 오픈소스 무료 제품 많음 |\n| **확장성** | 우수함 | 제한적 |\n| **동시 VM 개수** | 수십~수백 개 | 수 개~수십 개 |\n| **예시 제품** | ESXi, Hyper-V, XenServer, KVM | VirtualBox, VMware Workstation, Parallels |"
