            "label": "어떻게 작동하나",
            "body": "`.env` 파일에 `KEY=VALUE` 형식으로 적어두고, 앱이 시작할 때 라이브러리가 읽어 프로세스의 환경 변수로 올린다. 코드는 그 이름으로 값을 꺼낸다.\n\n```\nDATABASE_URL=postgresql://localhost:5432/myapp_dev\nAPI_TIMEOUT=30000\nDEBUG=true\n```\n\n이 파일은 `.gitignore` 에 넣어 버전 관리에서 뺀다. 대신 값을 지운 `.env.example` 을 같이 두어 어떤 변수가 필요한지 알린다.\n\n```도해\n층: 같은 이름이 여러 곳에 있으면 어느 값이 이기나\n직접 넘긴 값 :: 실행할 때 넘긴 것. 가장 세다\n.env 파일 :: 파일에서 읽어 올린 값\n코드 기본값 :: 위에 아무것도 없을 때만 쓰인다\n= 위가 아래를 덮는다. 그래서 운영에서는 위에서 주입한다\n```\n\n운영 환경에서는 파일 대신 시크릿 관리 서비스에서 값을 넣어주는 경우가 많다. AWS Secrets Manager, Azure Key Vault, HashiCorp Vault 같은 것들이 암호화와 접근 제어를 함께 맡는다."
