            "label": "왜 IDE가 필요한가?",
            "body": "### 텍스트 에디터만 사용할 때의 문제\n\n**문제 1: 여러 프로그램 왔다갔다**\n```\nVS Code로 코드 작성\n→ Terminal로 전환\n→ 명령어 실행\n→ 브라우저로 전환\n→ 결과 확인\n→ VS Code로 돌아와 수정\n\n→ 창 전환만 몇 초씩 ❌\n```\n\n**문제 2: 오류 찾기 어려움**\n```\nprint() 찍어가며 디버깅:\n→ 코드 수정\n→ 실행\n→ 로그 확인\n→ 다시 수정\n→ 반복...\n\n→ 10분씩 소요 ❌\n```\n\n### IDE의 해결\n\n```\n✅ 모든 기능이 한 곳에\n→ 코드 작성\n→ 바로 실행 (F5)\n→ 터미널 내장\n→ 창 전환 불필요\n\n✅ 똑똑한 도움\n→ 자동완성\n→ 오류 실시간 감지\n→ 리팩토링 도구\n→ Git 통합\n\n✅ 강력한 디버깅\n→ 중단점 (Breakpoint)\n→ 변수 실시간 확인\n→ 단계별 실행\n→ 빠른 오류 해결\n```"
