        "category": "AI · LLM",
        "summary": "Routing(라우팅)은 사용자 요청을 분석하여 **적절한 Agent나 서비스로 전달**하는 과정입니다. 마치 우체국이 편지를 올바른 주소로 배달하듯이, 요청을 정확한 처리자에게 보냅니다.",
