        "term": "Transformer",
        "reading": "트랜스포머",
        "category": "AI · LLM",
        "summary": "Transformer는 **Attention 메커니즘을 기반으로 한 딥러닝 아키텍처**입니다. 현대 LLM (GPT, BERT, Claude 등)의 핵심 기술입니다.",
        "definition": "",
        "analogy": "",
        "figure": "",
        "check": [],
        "sections": [
          {
            "slot": "why",
            "label": "Transformer가 해결하는 문제",
            "body": "**문제 상황**:\n```\n😱 시나리오 1: RNN의 순차 처리\n문장: \"나는 학교에 갔다\"\nRNN: 나 → 는 → 학교 → 에 → 갔다\n→ 순차적으로 한 단어씩! 😱\n→ 병렬 처리 불가! 😱\n→ 느림! 😱\n\n😱 시나리오 2: 장기 의존성 문제\n문장: \"어제 시장에서 산 사과를 오늘 먹었다\"\nRNN: \"사과\"와 \"먹었다\"의 관계 파악 어려움\n→ 거리가 멀면 정보 손실! 😱\n→ 문맥 이해 실패! 😱\n\n😱 시나리오 3: 학습 시간\n100만 개 문장 학습\nRNN: 며칠~몇 주\n→ GPU 병렬화 불가! 😱\n→ 학습 비효율! 😱\n```\n\n**Transformer의 해결**:\n```\n✅ 시나리오 1: 병렬 처리\n문장: \"나는 학교에 갔다\"\nTransformer: [나, 는, 학교, 에, 갔다] 동시 처리\n→ 모든 단어를 한 번에! ✅\n→ GPU 병렬화 가능! ✅\n→ 빠름! ✅\n\n✅ 시나리오 2: Self-Attention\n\"어제 시장에서 산 사과를 오늘 먹었다\"\nAttention: \"사과\" ↔ \"먹었다\" 직접 연결\n→ 거리와 무관하게 관계 파악! ✅\n→ 완벽한 문맥 이해! ✅\n\n✅ 시나리오 3: 빠른 학습\n100만 개 문장\nTransformer: 몇 시간~하루\n→ 완전 병렬화! ✅\n→ 학습 효율적! ✅\n```"
          },
          {
            "slot": "concept",
            "label": "핵심 개념",
            "body": "- **무엇인가?**: 순차 데이터를 병렬로 처리하는 신경망\n- **왜 필요한가?**: RNN보다 빠르고 긴 문맥 이해\n- **어떻게 작동하나?**: Self-Attention으로 관계 파악"
          },
          {
            "slot": "example",
            "label": "Transformer 아키텍처",
            "body": "### 핵심 구성 요소\n\n```\n1. Self-Attention\n→ 단어 간 관계 계산\n→ \"나는 학교에 갔다\"에서\n   \"갔다\"가 \"학교\"에 주목\n\n2. Multi-Head Attention\n→ 여러 관점에서 관계 파악\n→ 문법, 의미, 주제 등\n\n3. Positional Encoding\n→ 단어 순서 정보 추가\n→ \"나는 학교에 갔다\" vs \"학교에 나는 갔다\"\n\n4. Feed Forward\n→ 정보 변환\n→ 특징 추출\n```"
          },
          {
            "slot": "example",
            "label": "Attention 메커니즘",
            "body": "### Self-Attention 작동 원리\n\n```python\nimport numpy as np\n\ndef simple_attention(query, key, value):\n    \"\"\"간단한 Attention 구현\"\"\"\n    # 1. Query와 Key의 유사도 계산\n    scores = np.dot(query, key.T)\n\n    # 2. 소프트맥스로 가중치 변환\n    attention_weights = np.exp(scores) / np.sum(np.exp(scores))\n\n    # 3. Value에 가중치 적용\n    output = np.dot(attention_weights, value)\n\n    return output, attention_weights\n\n# 예시: 문장 \"나는 학교에 갔다\"\nwords = [\"나는\", \"학교에\", \"갔다\"]\n\n# 임베딩 (실제로는 더 큰 차원)\nembeddings = np.array([\n    [0.1, 0.2, 0.3],  # 나는\n    [0.4, 0.5, 0.6],  # 학교에\n    [0.7, 0.8, 0.9]   # 갔다\n])\n\n# \"갔다\"가 다른 단어들에 얼마나 주목하는지\nquery = embeddings[2]  # 갔다\nkeys = embeddings\nvalues = embeddings\n\noutput, weights = simple_attention(query, keys, values)\n\nprint(\"Attention 가중치:\")\nfor word, weight in zip(words, weights):\n    print(f\"  {word}: {weight:.3f}\")\n\n# 출력:\n# 나는: 0.090\n# 학교에: 0.244\n# 갔다: 0.665  ← 자기 자신에 가장 높은 가중치\n```\n\n### Multi-Head Attention\n\n```python\nimport torch\nimport torch.nn as nn\n\nclass MultiHeadAttention(nn.Module):\n    \"\"\"멀티 헤드 어텐션\"\"\"\n\n    def __init__(self, d_model=512, num_heads=8):\n        super().__init__()\n        self.num_heads = num_heads\n        self.d_model = d_model\n        self.d_k = d_model // num_heads"
          },
          {
            "slot": "example",
            "label": "Transformer 기반 모델들",
            "body": "### 1. GPT (Decoder-only)\n\n```\n아키텍처: Decoder만 사용\n특징: 다음 단어 예측 (자기회귀)\n용도: 텍스트 생성\n\n예시:\n입력: \"안녕하세요, 저는\"\n출력: \"파이썬 개발자입니다\"\n\n모델: GPT-3, GPT-4, LLaMA\n```\n\n### 2. BERT (Encoder-only)\n\n```\n아키텍처: Encoder만 사용\n특징: 양방향 문맥 이해\n용도: 분류, 질의응답\n\n예시:\n입력: \"나는 [MASK]에 갔다\"\n출력: [MASK] = \"학교\"\n\n모델: BERT, RoBERTa, ALBERT\n```\n\n### 3. T5 (Encoder-Decoder)\n\n```\n아키텍처: 전체 Transformer\n특징: 모든 작업을 텍스트 생성으로\n용도: 번역, 요약, QA\n\n예시:\n입력: \"translate English to Korean: Hello\"\n출력: \"안녕하세요\"\n\n모델: T5, BART, mBART\n```"
          },
          {
            "slot": "example",
            "label": "실전 활용",
            "body": "### PyTorch로 간단한 Transformer\n\n```python\nimport torch\nimport torch.nn as nn\n\nclass SimpleTransformer(nn.Module):\n    \"\"\"간단한 Transformer 모델\"\"\"\n\n    def __init__(self, vocab_size, d_model=512, nhead=8, num_layers=6):\n        super().__init__()\n\n        # Embedding\n        self.embedding = nn.Embedding(vocab_size, d_model)\n        self.pos_encoding = nn.Embedding(1000, d_model)\n\n        # Transformer Encoder\n        encoder_layer = nn.TransformerEncoderLayer(\n            d_model=d_model,\n            nhead=nhead,\n            dim_feedforward=2048\n        )\n        self.transformer = nn.TransformerEncoder(\n            encoder_layer,\n            num_layers=num_layers\n        )\n\n        # Output\n        self.fc_out = nn.Linear(d_model, vocab_size)\n\n    def forward(self, x):\n        # x: (batch_size, seq_len)\n        seq_len = x.size(1)\n\n        # Embedding + Positional Encoding\n        positions = torch.arange(0, seq_len).unsqueeze(0)\n        x = self.embedding(x) + self.pos_encoding(positions)\n\n        # Transformer\n        x = self.transformer(x)\n\n        # Output\n        x = self.fc_out(x)\n\n        return x\n\n# 모델 생성\nmodel = SimpleTransformer(vocab_size=10000, d_model=512, nhead=8)\n\n# 샘플 입력\nx = torch.randint(0, 10000, (2, 20))  # (batch_size=2, seq_len=20)\noutput = model(x)\n\nprint(f\"입력 크기: {x.shape}\")\nprint(f\"출력 크기: {output.shape}\")  # (2, 20, 10000)\n```"
          }
        ],
