        "definition": "팀마다 보는 숫자가 다르면 무엇을 먼저 할지 정하는 자리가 취향 다툼이 된다. 하나를 정해두면 각 기능이 그 숫자를 얼마나 움직이는지로 비교할 수 있다.",
        "analogy": "북극성. 배마다 가는 길은 달라도 같은 별을 보고 방향을 잡는다.",
