            "slot": "why",
            "label": "PMF가 해결하는 문제",
            "body": "**문제 상황**:\n```\n😱 PMF 이전 (Before PMF)\n\n시나리오 1: 아무도 안 씀\n100명 가입 → 5명만 활성 사용자\n→ 제품이 필요 없는 것! 😱\n\n시나리오 2: 이탈이 빠름\n신규 사용자: 많음\n재방문율: 5%\n→ 가치를 못 느낌! 😱\n\n시나리오 3: 추천 없음\n\"주변에 추천하시겠어요?\" → \"아니요\"\nNPS: -20\n→ 만족도 낮음! 😱\n\n시나리오 4: 마케팅 비효율\n광고비: 천만 원\n신규 가입: 100명\n→ 돈만 날림! 😱\n```\n\n**PMF 달성 후 (After PMF)**:\n```\n✅ 시나리오 1: 자발적 사용\n100명 가입 → 80명 활성 사용자\n→ 제품이 필요함! ✅\n\n✅ 시나리오 2: 높은 재방문\n신규 사용자: 많음\n재방문율: 60%\n→ 가치 제공! ✅\n\n✅ 시나리오 3: 입소문\n\"주변에 추천하시겠어요?\" → \"당연하죠!\"\nNPS: +50\n→ 열광적 반응! ✅\n\n✅ 시나리오 4: 자연 성장\n광고 안 해도 → 입소문으로 확산\n바이럴 계수 > 1\n→ 유기적 성장! ✅\n```"
