            "slot": "example",
            "label": "Wireframe 도구",
            "body": "### 무료 도구\n\n```python\nwireframe_tools = {\n    \"종이 + 펜\": {\n        \"장점\": \"가장 빠름, 제약 없음\",\n        \"단점\": \"공유 어려움\",\n        \"추천\": \"초기 아이디어 스케치\"\n    },\n\n    \"Excalidraw\": {\n        \"장점\": \"무료, 웹 기반, 협업 가능\",\n        \"단점\": \"기본 기능만\",\n        \"추천\": \"빠른 와이어프레임\"\n    },\n\n    \"Figma (Free)\": {\n        \"장점\": \"전문적, 협업 우수, 프로토타입\",\n        \"단점\": \"러닝 커브\",\n        \"추천\": \"Mid-High fidelity\"\n    },\n\n    \"Balsamiq\": {\n        \"장점\": \"와이어프레임 특화, 손그림 느낌\",\n        \"단점\": \"유료\",\n        \"추천\": \"전통적 와이어프레임\"\n    }\n}\n```\n\n### HTML/CSS 간단 와이어프레임\n\n```html\n<!DOCTYPE html>\n<html>\n<head>\n<style>\n/* 와이어프레임 스타일 */\n* {\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n}\n\nbody {\n    font-family: Arial, sans-serif;\n    background: #fff;\n    color: #333;\n}\n\n.wireframe-box {\n    border: 2px solid #333;\n    padding: 20px;\n    margin: 10px;\n    background: #f9f9f9;\n    text-align: center;\n}\n\nheader {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    border-bottom: 2px solid #333;\n    padding: 20px;\n}\n\n.logo { font-size: 24px; font-weight: bold; }\n\n.hero {\n    height: 300px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 32px;\n}\n\n.products {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 20px;\n    padding: 20px;\n}\n\n.product-card {\n    height: 200px;\n}"
