            "body": "### ✅ 해야 할 것\n\n```python\nbest_practices = {\n    \"1. 단순하게\": {\n        \"설명\": \"색상, 이미지 최소화\",\n        \"이유\": \"구조에 집중\",\n        \"예시\": \"회색 박스로 이미지 표시\"\n    },\n\n    \"2. 실제 콘텐츠 사용\": {\n        \"설명\": \"Lorem ipsum 대신 실제 텍스트\",\n        \"이유\": \"길이, 가독성 확인\",\n        \"예시\": \"'상품명' 대신 '나이키 에어맥스'\"\n    },\n\n    \"3. 인터랙션 표시\": {\n        \"설명\": \"클릭, 호버 등 명시\",\n        \"이유\": \"동작 이해\",\n        \"예시\": \"버튼 클릭 → 페이지 이동 화살표\"\n    },\n\n    \"4. 주석 추가\": {\n        \"설명\": \"의도, 기능 설명\",\n        \"이유\": \"명확한 소통\",\n        \"예시\": \"검색: 3글자 이상 입력 시 제안\"\n    },\n\n    \"5. 모바일도 고려\": {\n        \"설명\": \"반응형 레이아웃\",\n        \"이유\": \"모바일 우선\",\n        \"예시\": \"PC + 모바일 와이어프레임\"\n    }\n}\n```\n\n### ❌ 피해야 할 것\n\n```python\nanti_patterns = {\n    \"1. 너무 상세하게\": {\n        \"문제\": \"색상, 폰트까지 결정\",\n        \"결과\": \"시간 낭비, 디자이너 역할 침범\",\n        \"해결\": \"회색톤만 사용\"\n    },\n\n    \"2. Lorem ipsum 남용\": {\n        \"문제\": \"'Lorem ipsum dolor sit...'\",\n        \"결과\": \"실제 콘텐츠 길이 파악 안 됨\",\n        \"해결\": \"실제 텍스트 사용\"\n    },\n\n    \"3. 혼자 작업\": {\n        \"문제\": \"PM 혼자 완성\",\n        \"결과\": \"디자이너/개발자 의견 누락\",\n        \"해결\": \"함께 스케치\"\n    },\n\n    \"4. 와이어프레임 = 최종\": {\n        \"문제\": \"와이어프레임대로 개발\",\n        \"결과\": \"디자인 단계 생략\",\n        \"해결\": \"디자인 → 개발 순서\"\n    }\n}\n```"
